package com.veyra.chat;
import com.veyra.security.CurrentUser;import com.veyra.shared.ApiException;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.messaging.simp.SimpMessagingTemplate;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/bookings/{bookingId}/chat")public class ChatController{private final JdbcTemplate db;private final SimpMessagingTemplate ws;public ChatController(JdbcTemplate d,SimpMessagingTemplate w){db=d;ws=w;}public record Msg(String body){}
 @PostMapping("/messages")ResponseEntity<Map<String,Object>>send(@PathVariable UUID bookingId,@RequestBody Msg m){participant(bookingId);if(m.body()==null||m.body().isBlank()||m.body().length()>2000)throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_MESSAGE");UUID c=conversation(bookingId),id=UUID.randomUUID(),u=CurrentUser.id();db.update("insert into chat_messages(id,conversation_id,sender_user_id,body) values (?,?,?,?)",id,c,u,m.body());Map<String,Object>x=Map.of("id",id,"senderUserId",u,"body",m.body());ws.convertAndSend("/topic/bookings/"+bookingId+"/chat",x);return ResponseEntity.status(201).body(x);}
 @GetMapping("/messages")List<Map<String,Object>>list(@PathVariable UUID bookingId){participant(bookingId);return db.queryForList("select cm.id,cm.sender_user_id,cm.body,cm.status,cm.sent_at,cm.read_at from chat_messages cm join chat_conversations c on c.id=cm.conversation_id where c.booking_id=? order by cm.sent_at",bookingId);}
 private UUID conversation(UUID b){List<UUID>x=db.queryForList("select id from chat_conversations where booking_id=?",UUID.class,b);if(!x.isEmpty())return x.getFirst();UUID id=UUID.randomUUID();db.update("insert into chat_conversations(id,booking_id) values (?,?)",id,b);return id;}
 private void participant(UUID b){UUID u=CurrentUser.id();Integer n=db.queryForObject("select count(*) from scheduled_bookings sb left join drivers d on d.id=sb.selected_driver_id left join partner_users pu on pu.partner_id=sb.partner_id and pu.user_id=? where sb.id=? and sb.status in ('CONFIRMED','DRIVER_EN_ROUTE','DRIVER_ARRIVED','IN_PROGRESS','COMPLETED','CLOSED') and (sb.creator_user_id=? or d.user_id=? or pu.id is not null)",Integer.class,u,b,u,u);if(n==0)throw new ApiException(HttpStatus.FORBIDDEN,"CHAT_NOT_ALLOWED");}
}